css:
body{--k-accent:#17313A;--k-accent-dark:#0D2128;--k-accent-2:#1E8C74;--k-soft:#E4ECEB;--k-ink:#17262B;--k-muted:#56676C;--k-line:#D3DCDB;--k-panel:#FFFFFF;--k-bg:#F1F4F3;--k-warn:#D08A1E;--k-good:#1E8C74;--k-bad:#B5452F;--k-radius:6px;--k-shadow:none;
 --s-reg:#2F6FB5;--s-care:#1E8C74;--s-pay:#D08A1E;--before:#BAC5C7;--chart-1:#17313A;--chart-2:#1E8C74;--chart-3:#D08A1E;--chart-4:#2F6FB5;--chart-5:#B5452F;--chart-6:#8A9A9E;--chart-ink:#17262B;--chart-muted:#56676C;--chart-grid:#E1E8E7;
 font-family:"Malgun Gothic","Apple SD Gothic Neo","Noto Sans KR",sans-serif}
.deck-mark i{background:linear-gradient(90deg,var(--s-reg) 0 33%,var(--s-care) 33% 66%,var(--s-pay) 66%)!important;width:30px!important;border-radius:3px}
.chapter-tab.active{background:var(--k-ink)}
#stage.composed-scene,.print-stage.composed-scene{padding:36px 64px 32px;gap:14px}
.composed-scene .eyebrow{display:flex;align-items:center;gap:12px;color:var(--k-muted);font-size:18px;font-weight:700;margin:4px 0 0}
.composed-scene .eyebrow::before{content:"";flex:none;width:48px;height:6px;border-radius:3px;background:linear-gradient(90deg,var(--s-reg) 0 32%,transparent 32% 34%,var(--s-care) 34% 66%,transparent 66% 68%,var(--s-pay) 68%)}
.composed-scene .scene-title{font-size:44px;font-weight:800;letter-spacing:-.035em;line-height:1.18;color:var(--k-ink);margin:0}
.composed-scene .scene-title em{color:var(--s-care)}
.lead.summary{background:#fff;border:1px solid var(--k-line);border-left:6px solid var(--k-ink);border-radius:6px;font-size:19px;font-weight:600;padding:9px 18px;font-variant-numeric:tabular-nums}
.composed-scene .scene-bottom{border-top:0;background:var(--k-ink);color:#fff;border-radius:6px;padding:11px 20px;display:flex;align-items:center;gap:18px}
.composed-scene .message{font-size:19px;font-weight:600;margin:0;flex:1}
.composed-scene .message-label{background:var(--s-care);color:#fff;font-size:15px}
.composed-scene .source{color:#ffffffb0;font-size:13px;margin:0;white-space:nowrap}
.k-panel{border-radius:6px;box-shadow:none;padding:18px 22px}
.k-panel-head{font-size:19px}
.reveal-spotlight [data-step].focus{box-shadow:0 0 0 2px var(--k-ink)}
svg [data-step].focus{filter:none}
.reveal-spotlight [data-step].dim{opacity:.3}
.num{font-variant-numeric:tabular-nums}
svg text{font-family:inherit}
.t-axis{font-size:15px;fill:var(--k-muted)}
.t-lab{font-size:18px;font-weight:700;fill:var(--k-ink)}
.t-val{font-size:20px;font-weight:800;fill:var(--k-ink)}
.t-in{font-size:17px;font-weight:700;fill:#fff}
.on-pay{fill:var(--k-ink)}
.t-mut{font-size:16px;fill:var(--k-muted)}
.grid-l{stroke:var(--chart-grid);stroke-width:1}
.base-l{stroke:#8E9C9F;stroke-width:1.5}
.target-l{stroke:var(--k-ink);stroke-width:2;stroke-dasharray:7 6}
.f-reg{fill:var(--s-reg)}.f-care{fill:var(--s-care)}.f-pay{fill:var(--s-pay)}.f-before{fill:var(--before)}.f-ink{fill:var(--k-ink)}
.dot{display:inline-block;width:14px;height:14px;border-radius:3px;margin-right:8px;vertical-align:-1px}
.d-reg{background:var(--s-reg)}.d-care{background:var(--s-care)}.d-pay{background:var(--s-pay)}.d-before{background:var(--before)}.d-ink{background:var(--k-ink)}
.legend{display:flex;gap:22px;font-size:16px;color:var(--k-muted);font-weight:600}
.grow{transform-box:fill-box;transform-origin:left center}
@keyframes grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes draw{from{stroke-dashoffset:var(--len)}to{stroke-dashoffset:0}}
@keyframes pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:scale(1)}}
[data-step].focus .grow{animation:grow .9s cubic-bezier(.2,.7,.2,1) both}
@media (prefers-reduced-motion: reduce){[data-step].focus .grow,[data-scene] .draw,[data-scene] .pop{animation:none!important}}
@media print{.grow,.draw,.pop{animation:none!important}}
@media print{.print-stage{transform:none!important;zoom:.65375}}

.jr-row{display:grid;grid-template-columns:44px 1fr auto;align-items:center;gap:14px;padding:12px 0;border-bottom:1px solid var(--k-line)}
.jr-row:last-child{border-bottom:0}
.jr-row b{font-size:20px}.jr-row .jr-ba{font-size:20px;font-weight:700}.jr-row .jr-d{font-size:24px;font-weight:800;text-align:right}
.jr-row .jr-d small{display:block;font-size:14px;font-weight:600;color:var(--k-muted)}
.stripe{height:100%;min-height:52px;border-radius:3px}
.callout{border-left:6px solid var(--s-care)!important}
.callout .big{font-size:52px;font-weight:800;letter-spacing:-.03em;line-height:1}
.mix{display:flex;gap:2px;height:40px;margin-top:auto}.mix i.d-pay{color:var(--k-ink)}.mix i{display:grid;place-items:center;color:#fff;font-style:normal;font-weight:800;font-size:17px;border-radius:3px}
.callout .big small{font-size:22px;color:var(--k-muted);font-weight:700;margin-left:4px}

[data-scene="cover"] .scene-title{font-size:60px;letter-spacing:-.04em}
.cover{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:40px;align-items:center;flex:1;min-height:0}
.cv-l{font-size:24px;font-weight:700;color:var(--k-muted);margin:0 0 8px}
.cv-row{display:flex;align-items:baseline;gap:22px;font-variant-numeric:tabular-nums}
.cv-old{font-size:84px;font-weight:800;color:var(--k-muted);text-decoration:line-through;text-decoration-thickness:5px;text-decoration-color:#8E9C9F}
.cv-arrow{font-size:60px;color:var(--k-muted)}
.cv-new{font-size:170px;font-weight:800;letter-spacing:-.05em;line-height:.9;color:var(--k-ink)}
.cv-sub{font-size:24px;margin:22px 0 0;font-weight:600}
.cv-sub b{color:var(--s-care)}
.cv-fic{font-size:15px;color:var(--k-muted);margin:16px 0 0}
.draw{fill:none;stroke-linecap:round;stroke-dasharray:var(--len)}
[data-step].focus .draw{animation:draw 1.8s cubic-bezier(.3,.6,.2,1) both}
.hero-n{font-size:190px;font-weight:800;letter-spacing:-.06em;line-height:.85;color:var(--k-ink);font-variant-numeric:tabular-nums}
.hero-n small{font-size:56px;letter-spacing:-.02em;margin-left:6px}
.hero-d{margin-top:22px;font-size:28px;font-weight:800;color:var(--s-care)}
.kpi-row{display:grid;grid-template-columns:1fr auto;align-items:baseline;gap:4px 16px;padding:14px 0;border-bottom:1px solid var(--k-line)}
.kpi-row:last-child{border-bottom:0}
.kpi-row .lab{font-size:19px;font-weight:700}
.kpi-row .val{font-size:30px;font-weight:800;text-align:right;font-variant-numeric:tabular-nums}
.kpi-row .val s{color:var(--k-muted);font-weight:700;text-decoration:none;font-size:22px}
.kpi-row .note{grid-column:1/3;font-size:15px;color:var(--k-muted)}
.ask-strip{background:var(--k-ink)!important;color:#fff;border-color:var(--k-ink)!important;flex-direction:row!important;align-items:center;justify-content:space-between}
.ask-strip .lab{font-size:18px;color:#ffffffc0;font-weight:700}
.ask-strip .val{font-size:30px;white-space:nowrap;font-weight:800}
.ask-strip button[data-goto]{white-space:nowrap;flex:none;background:transparent;color:#fff;border-color:#ffffff80;font-size:15px;padding:8px 14px}
.chain{display:flex;align-items:center;gap:12px}
.chain div{flex:1;border:2px solid var(--k-ink);border-radius:6px;padding:14px 16px;font-size:20px;font-weight:700;text-align:center;background:#fff}
.chain span{font-size:28px;color:var(--k-muted)}
.target-big{font-size:64px;font-weight:800;letter-spacing:-.03em;line-height:1}
.target-big small{font-size:26px;color:var(--k-muted);margin-left:6px}
.fact{font-size:20px}
.fact b{font-size:34px;font-weight:800;margin-right:6px}
.invest{display:flex;gap:2px;height:64px}
.invest div{display:flex;align-items:center;justify-content:space-between;padding:0 16px;color:#fff;font-weight:800;font-size:19px;border-radius:3px;white-space:nowrap;overflow:hidden}
.invest .d-pay{color:var(--k-ink)}
.lane{border-top:8px solid var(--c)!important;gap:14px!important}
.lane h3{font-size:25px;margin:0;letter-spacing:-.02em}
.lane .money{font-size:40px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1}
.lane .money small{font-size:18px;color:var(--k-muted);margin-left:8px}
.lane .tgt{border-top:1px solid var(--k-line);padding-top:12px;font-size:18px}
.lane .tgt b{display:block;font-size:30px;font-variant-numeric:tabular-nums}
.side-note{border-left:5px solid var(--k-ink)!important;gap:6px!important}
.side-note h4{font-size:17px;color:var(--k-muted);font-weight:700}
.side-note p{font-size:20px;font-weight:700;line-height:1.35}
.side-note p b{font-size:30px}
.sat h3{font-size:22px;margin:0}
.sat .delta{font-size:44px;font-weight:800;color:var(--s-care);line-height:1;font-variant-numeric:tabular-nums}
.sat .delta small{font-size:17px;color:var(--k-muted);font-weight:600;margin-left:8px}
.task{background:var(--k-ink)!important;color:#fff;border-color:var(--k-ink)!important;justify-content:center;gap:18px!important}
.task h3{font-size:34px;line-height:1.3;letter-spacing:-.02em}
.task p{font-size:22px;color:#ffffffd0}
.task .tag{align-self:flex-start;background:var(--s-pay);color:var(--k-ink);font-weight:800;padding:4px 12px;border-radius:4px;font-size:16px}
.ask-panel{background:var(--k-ink)!important;color:#fff;border-color:var(--k-ink)!important;justify-content:center;gap:16px!important;padding:36px 40px!important}
.ask-panel .lab{font-size:22px;color:#ffffffc0;font-weight:700}
.ask-panel .amt{font-size:84px;white-space:nowrap;font-weight:800;letter-spacing:-.04em;line-height:1}
.ask-panel .what{font-size:24px;font-weight:700}
.ask-panel .per{font-size:17px;color:#ffffffb0}
.plan{margin:0;padding:0;list-style:none;display:grid;gap:22px}
.plan li{display:grid;grid-template-columns:auto 1fr;gap:14px;align-items:baseline;font-size:24px;font-weight:600}
.plan li b{font-size:15px;background:var(--k-soft);padding:3px 10px;border-radius:4px;color:var(--k-ink)}
.bk .k-table{font-size:19px}
.bk .k-table td,.bk .k-table th{padding:16px 14px}
.bk .k-table th{background:#fff;color:var(--k-muted);border-bottom:2px solid var(--k-ink)}
.minibar{display:block;position:relative;height:14px;background:var(--k-soft);border-radius:3px;min-width:260px}
.minibar i{position:absolute;top:0;bottom:0;border-radius:3px}
.over{color:var(--k-bad);font-weight:800}
